$ErrorActionPreference="Stop";$R="https://raw.githubusercontent.com/alamaxjashek/OfficeDeploy/main";$D="$env:ProgramData\OfficeDeploy";New-Item $D -ItemType Directory -Force|Out-Null;"WINWORD","EXCEL","POWERPNT","OUTLOOK","MSACCESS","ONENOTE","MSPUB","VISIO","WINPROJ","OfficeClickToRun"|ForEach-Object{Get-Process $_ -ErrorAction SilentlyContinue|Stop-Process -Force -ErrorAction SilentlyContinue};Invoke-WebRequest "$R/setup.exe" -OutFile "$D\setup.exe";Invoke-WebRequest "$R/uninstall.xml" -OutFile "$D\uninstall.xml";$P=Start-Process "$D\setup.exe" -ArgumentList "/configure `"$D\uninstall.xml`"" -Wait -PassThru;Start-Sleep 10;$O=Get-ItemProperty HKLM:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*,HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\* -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName -match "Microsoft 365|Microsoft Office|Office 16 Click-to-Run"};if($O){Write-Host "OFFICE TODAVIA DETECTADO:" -ForegroundColor Red;$O|Select DisplayName,DisplayVersion|Format-Table -AutoSize;exit 1}else{Write-Host "OFFICE ELIMINADO CORRECTAMENTE" -ForegroundColor Green;exit 0}